function execProfile(job,roll){const j=Object.hasOwn(execJobs,job)?execJobs[job]:null;if(!j||!Number.isInteger(roll)||roll<1||roll>6)return null;const row=j.stats[roll-1],stats=Object.fromEntries(['INT','REF','DEX','TECH','COOL','WILL','MOVE','BODY','EMP'].map((k,i)=>[k,row[i]]));return {job,roll,stats,hp:10+5*Math.ceil((stats.BODY+stats.WILL)/2),deathSave:stats.BODY}}
function execSkillText(skills,l){if(l!=='ru')return skills;return skills.split(', ').map(skill=>{if(skill==='Interface (Netrunner Role Ability)')return 'Interface (способность нетраннера)';const doubled=skill.endsWith(' (x2)'),name=doubled?skill.slice(0,-5):skill,key=name==='Local Expert (Your Home)'?'Local Expert (Home)':name,translated=window.SKILL_LABELS?.[key]?.ru;return (typeof translated==='string'&&translated?translated:name)+(doubled?' (×2)':'')}).join(', ')}
function execMemberDetails(m,l,i){const t=m?.execProfile;if(t===undefined)return '';const ru=l==='ru';if(!roleObj(t)||t.version!==1||!execProfile(t.job,t.roll))return `<p class="rt-warning">${ru?'Формат профиля сотрудника несовместим; данные не изменены.':'Team profile data is incompatible; it was not changed.'}</p>`;const p=execProfile(t.job,t.roll),j=execJobs[t.job],hp=m.hp===undefined?p.hp:m.hp,hpValid=Number.isSafeInteger(hp)&&hp>=-999&&hp<=1000;return `<details><summary>${esc(x(j.name,l))} · ${ru?'характеристики и оснащение':'stats and equipment'} · d6 ${p.roll}</summary><p>${esc(Object.entries(p.stats).map(([k,v])=>`${k} ${v}`).join(' · '))}</p><p>${ru?'Максимум':'Maximum'} HP ${p.hp} · ${ru?'Тяжело ранен при HP ниже':'Seriously Wounded below'} ${Math.ceil(p.hp/2)} · ${ru?'Смертельно ранен при HP ≤ 0':'Mortally Wounded at HP ≤ 0'} · Death Save ${p.deathSave}</p>${hpValid?`<label class="rt-field">${ru?'Текущие HP':'Current HP'}<input type="number" data-rt-team="${i}" data-rt-key="hp" value="${hp}" min="-999" max="1000"></label>`:`<p class="rt-warning">${ru?'Неизвестный формат HP сотрудника; данные не изменены.':'Incompatible team member HP; data was not changed.'}</p>`}<p>${ru?'Прикрытие':'Cover'}: ${esc(x(j.cover,l))}</p><p>+2: ${esc(execSkillText(j.s2,l))}</p><p>+4: ${esc(execSkillText(j.s4,l))}</p><p>+6: ${esc(execSkillText(j.s6,l))}</p><p>${ru?'Киберимпланты':'Cyberware'}: ${esc(x(j.cyber,l))}</p><p>${ru?'Снаряжение':'Gear'}: ${esc(x(j.gear,l))}</p></details>`}
function execGenerate(e,c,l,options){const b=e.type==='click'?e.target?.closest?.('[data-rt-action]'):null;if(b?.dataset?.rtAction!=='team-generate')return {handled:false};const ru=l==='ru',msg=(a,b)=>ru?a:b,root=b.closest?.('[data-rt-root]'),get=k=>root?.querySelector?.(`[data-exec-${k}]`),job=get('job'),replacement=get('replacement'),snapshot=()=>{try{return JSON.stringify(c)}catch{return null}},same=()=>{try{return c.role==='exec'&&roleCompatible(c)&&root?.isConnected===true&&b.isConnected===true&&b.closest?.('[data-rt-root]')===root&&job?.isConnected===true&&replacement?.isConnected===true&&root.querySelector('[data-exec-job]')===job&&root.querySelector('[data-exec-replacement]')===replacement&&typeof options.isCurrent==='function'&&options.isCurrent(c)===true}catch{return false}},stale=msg('Данные или аккаунт изменились; повторите действие.','Data or account changed; try again.');if(!same())return {handled:true,notify:stale};const key=job.value,replaced=!!replacement.checked,before=snapshot();if(!before||!Object.hasOwn(execJobs,key))return {handled:true,notify:msg('Выберите должность.','Choose a job.')};const team=c.extra?.roleTools?.exec?.team||[];if(team.length>=1000)return {handled:true,notify:msg('Достигнут лимит списка сотрудников.','The team list limit has been reached.')};if(!confirm(msg('Создать сотрудника? Бросок характеристик будет сделан сейчас.','Create the team member? The STAT roll will be made now.')+(replaced?msg(' Замена: Loyalty 1, расходы на найм 200 eb учитываются отдельно.',' Replacement: Loyalty 1; track the 200 eb hiring fee separately.') : '')))return {handled:true};if(!same()||snapshot()!==before||job.value!==key||!!replacement.checked!==replaced)return {handled:true,notify:stale};const newId=id();if(team.some(m=>m.id===newId))return {handled:true,notify:stale};const roll=die(6),loyalty=replaced?1:die(6)+1,p=execProfile(key,roll),s=init(c);s.team.push({id:newId,name:'',loyalty,hp:p.hp,execProfile:{version:1,job:key,roll}});setLast(s,`${x(execJobs[key].name,l)} · STAT d6 ${roll} · Loyalty ${loyalty} · HP ${p.hp}`);return {handled:true,dirty:true,rerender:true}}
// Operator deals are a calculation only: they never debit money or create inventory.
function quoteFixerDeal(input){
 const parse=(v,min,max)=>{if(typeof v!=='number'&&typeof v!=='string')return null;const s=String(v).trim();if(!/^\d+$/.test(s))return null;const n=Number(s);return Number.isSafeInteger(n)&&n>=min&&n<=max?n:null};
 const rank=parse(input?.rank,1,10),unit=parse(input?.unit,1,999999999),qty=parse(input?.quantity,1,10000),deal=input?.deal,direction=input?.direction,required={percent10:1,bonus:3,job20:5,installments:7,percent20:9,dangerous:10};
 if(rank===null||unit===null||qty===null||!Object.hasOwn(required,deal)||!['buy','sell'].includes(direction)||!['decrease','increase'].includes(input?.priceChange)||!['other','luxury','super'].includes(input?.category)||typeof input?.danger!=='boolean'||input?.success!==true)return {ok:false,reason:'invalid'};
 if(rank<required[deal])return {ok:false,reason:'rank'};
 if(unit*qty>999999999)return {ok:false,reason:'amount'};
 if((deal==='bonus'||deal==='installments')&&direction!=='buy')return {ok:false,reason:'buy'};
 if(deal==='bonus'&&qty<5)return {ok:false,reason:'quantity'};
 if(deal==='installments'&&(qty!==1||!['luxury','super'].includes(input.category)))return {ok:false,reason:'category'};
 if(deal==='dangerous'&&!input.danger)return {ok:false,reason:'danger'};
 const base=unit*qty,cents=base*100,result={ok:true,deal,direction,unit,quantity:qty,base,requiredRank:required[deal]};
 if(deal==='percent10'||deal==='percent20'){const percent=deal==='percent10'?10:20;result.totalCents=cents*(input.priceChange==='decrease'?100-percent:100+percent)/100;result.percent=percent;result.priceChange=input.priceChange}
 if(deal==='bonus'){result.totalCents=cents;result.free=1;result.received=qty+1}
 if(deal==='job20'||deal==='dangerous'){const multiplier=deal==='job20'?120:200;result.perPersonCents=unit*multiplier;result.totalCents=cents*multiplier/100}
 if(deal==='installments'){result.totalCents=cents;result.nowCents=cents/2;result.laterCents=cents/2}
 return result;
}
const fixerDealText={ru:{title:'РАСЧЁТ УСЛОВИЙ СДЕЛКИ',intro:'Подтвердите успешный встречный торг и выберите ровно одно условие. Это расчёт: деньги, инвентарь и долг не меняются.',success:'Торг успешно завершён',deal:'Условие Operator',direction:'Сторона сделки',buy:'Покупка',sell:'Продажа',unit:'Цена за предмет или оплата одному участнику, eb',qty:'Количество одинаковых предметов или участников',category:'Категория предмета для рассрочки',other:'Другая',luxury:'Luxury',super:'Super Luxury',danger:'Работа признана опасной ведущим',calculate:'Рассчитать сделку',start:'Введите цену, количество и подтвердите успешный торг.',base:'До сделки',total:'После сделки',perPerson:'На одного участника',free:'Дополнительный бесплатный предмет',received:'Всего предметов',now:'Сейчас',later:'Через месяц',note:'Одна сделка на транзакцию. Для работы применяется оплата за каждого участника; опасность определяет ведущий. Если не оплатить вторую половину вовремя, эту рассрочку больше никто не предоставит. Округление нестандартных дробных сумм согласуйте с ведущим.',invalid:'Подтвердите успех и введите целые положительные цену и количество.',rank:'Эта сделка недоступна на текущем ранге Operator.',amount:'Общая сумма слишком велика для расчёта.',buyOnly:'Это условие доступно только при покупке.',quantity:'Нужно купить как минимум пять одинаковых предметов.',categoryError:'Для рассрочки выберите один предмет категории Luxury или Super Luxury.',dangerError:'Ведущий должен подтвердить, что работа опасна.',names:['Скидка/наценка 10% · ранг 1','Ещё один предмет при покупке 5+ · ранг 3','Оплата работы +20% · ранг 5','Половина сейчас, половина через месяц · ранг 7','Скидка/наценка 20% · ранг 9','Двойная оплата опасной работы · ранг 10']},en:{title:'DEAL CALCULATOR',intro:'Confirm the opposed Haggle succeeded and select exactly one deal. This calculation does not change money, inventory or debt.',success:'The Haggle succeeded',deal:'Operator deal',direction:'Transaction side',buy:'Buy',sell:'Sell',unit:'Price per item or pay per person, eb',qty:'Number of identical items or team members',category:'Item category for installments',other:'Other',luxury:'Luxury',super:'Super Luxury',danger:'The GM has confirmed this is a dangerous job',calculate:'Calculate deal',start:'Enter the price and quantity and confirm a successful Haggle.',base:'Before deal',total:'After deal',perPerson:'Per person',free:'Additional free item',received:'Total items received',now:'Now',later:'In one month',note:'One deal per transaction. Job pay is per person; the GM determines danger. Missing the second payment means nobody will offer this installment deal again. Agree rounding for unusual fractional amounts with the GM.',invalid:'Confirm success and enter a positive whole price and quantity.',rank:'This deal is not available at the current Operator rank.',amount:'The total is too large to calculate.',buyOnly:'This deal applies only when buying.',quantity:'Buy at least five identical items.',categoryError:'Installments require one Luxury or Super Luxury item.',dangerError:'The GM must confirm that the job is dangerous.',names:['10% discount or premium · rank 1','One extra item when buying 5+ · rank 3','Job pay +20% · rank 5','Half now, half in a month · rank 7','20% discount or premium · rank 9','Double dangerous-job pay · rank 10']}};
